#################################################################

# BuyerRole: an AgentRole assigned in an OrganizationRoleAssignment whose NADSegment has qualifier 'BY'
:BuyerRole owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
        :AgentRole
        [
            a owl:Restriction ;
            owl:onProperty :isRoleAssignedIn ;
            owl:someValuesFrom [
                a owl:Class ;
                owl:intersectionOf (
                    :OrganizationRoleAssignment
                    [
                        a owl:Restriction ;
                        owl:onProperty :assignedRole ;
                        owl:hasValue :BuyerRole
                    ]
                    [
                        a owl:Restriction ;
                        owl:onProperty :isRepresentedByNADSegment ;
                        owl:someValuesFrom [
                            a owl:Restriction ;
                            owl:onProperty :hasNADPartyQualifier ;
                            owl:hasValue :NAD_BY
                        ]
                    ]
                )
            ]
        ]
    )
] .

# DeliveryPartyRole: an AgentRole assigned in an OrganizationRoleAssignment whose NADSegment has qualifier 'DP'
:DeliveryPartyRole owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
        :AgentRole
        [
            a owl:Restriction ;
            owl:onProperty :isRoleAssignedIn ;
            owl:someValuesFrom [
                a owl:Class ;
                owl:intersectionOf (
                    :OrganizationRoleAssignment
