                        a owl:Restriction ;
                        owl:onProperty :assignedRole ;
                        owl:hasValue :DeliveryPartyRole
                    ]
                    [
                        a owl:Restriction ;
                        owl:onProperty :isRepresentedByNADSegment ;
                        owl:someValuesFrom [
                            a owl:Restriction ;
                            owl:onProperty :hasNADPartyQualifier ;
                            owl:hasValue :NAD_DP
                        ]
                    ]
                )
            ]
        ]
    )
] .

